import { homedir } from "node:os";
import { join, resolve } from "node:path";

export interface InstallationPaths {
  root: string;
  releases: string;
  current: string;
  bin: string;
  shim: string;
  state: string;
}

export function installationPaths(): InstallationPaths {
  const root = resolve(
    process.env.BROWSERJACK_HOME ?? join(homedir(), "Library/Application Support/browserjack"),
  );
  const bin = join(root, "bin");
  return {
    root,
    releases: join(root, "releases"),
    current: join(root, "current"),
    bin,
    shim: join(bin, "browserjack"),
    state: join(root, "state.json"),
  };
}

import { setupBridge, type SetupResult } from "./setup.js";
import { readInstallState } from "./state.js";

export interface UpdateResult extends SetupResult {
  previousVersion: string;
}

export async function updateBridge(): Promise<UpdateResult> {
  const state = await readInstallState();
  if (state === null) {
    throw new Error("browserjack is not installed. Run browserjack setup first.");
  }

  const result = await setupBridge({
    scope: state.mcpScope,
    mcpName: state.mcpName,
    registerMcp: state.mcpRegistered,
    cwd: state.registrationCwd,
  });

  return { ...result, previousVersion: state.version };
}

import { constants } from "node:fs";
import { access, realpath } from "node:fs/promises";
import { delimiter, join } from "node:path";

export async function resolveExecutable(name: string): Promise<string> {
  const override = process.env[`${name.toUpperCase()}_CLI_PATH`];
  const candidates = override
    ? [override]
    : (process.env.PATH ?? "").split(delimiter).map((dir) => join(dir, name));

  for (const candidate of candidates) {
    try {
      await access(candidate, constants.X_OK);
      return await realpath(candidate);
    } catch {
      // Continue through PATH.
    }
  }
  throw new Error(`Unable to find executable ${name}`);
}

import { rm } from "node:fs/promises";

import { removeClaudeMcpIfOwned } from "./mcp.js";
import { installationPaths } from "./paths.js";
import { readInstallState } from "./state.js";

export async function uninstallBridge(keepState: boolean): Promise<void> {
  const paths = installationPaths();
  const state = await readInstallState();
  const mcpName = state?.mcpName ?? "browserjack";
  const scope = state?.mcpScope ?? "user";
  const mcpRegistered = state?.mcpRegistered ?? true;
  const registrationCwd = state?.registrationCwd ?? process.cwd();

  if (mcpRegistered) {
    await removeClaudeMcpIfOwned(mcpName, paths.shim, scope, registrationCwd);
  }
  if (keepState) {
    await rm(paths.current, { force: true });
    await rm(paths.shim, { force: true });
    return;
  }
  await rm(paths.root, { recursive: true, force: true });
}

import { readFile } from "node:fs/promises";

import { isJsonObject } from "../lib/json.js";
import { installationPaths } from "./paths.js";

export type McpScope = "user" | "local" | "project";

export interface InstallState {
  packageName: string;
  version: string;
  nodePath: string;
  mcpName: string;
  mcpScope: McpScope;
  mcpRegistered: boolean;
  registrationCwd: string;
}

function parseScope(value: unknown): McpScope | undefined {
  return value === "user" || value === "local" || value === "project" ? value : undefined;
}

export async function readInstallState(): Promise<InstallState | null> {
  const paths = installationPaths();
  let value: unknown;
  try {
    value = JSON.parse(await readFile(paths.state, "utf8"));
  } catch {
    return null;
  }
  if (!isJsonObject(value) || value.schemaVersion !== 1) {
    return null;
  }
  const scope = parseScope(value.mcpScope);
  if (
    typeof value.packageName !== "string" ||
    typeof value.version !== "string" ||
    typeof value.nodePath !== "string" ||
    typeof value.mcpName !== "string" ||
    scope === undefined ||
    typeof value.mcpRegistered !== "boolean"
  ) {
    return null;
  }
  return {
    packageName: value.packageName,
    version: value.version,
    nodePath: value.nodePath,
    mcpName: value.mcpName,
    mcpScope: scope,
    mcpRegistered: value.mcpRegistered,
    // Older states predate registrationCwd; fall back to the current directory.
    registrationCwd:
      typeof value.registrationCwd === "string" ? value.registrationCwd : process.cwd(),
  };
}

import { access, lstat, readFile, readlink, realpath } from "node:fs/promises";
import { join } from "node:path";

import { isJsonObject } from "../lib/json.js";
import { packageRoot } from "../lib/package-root.js";
import { inspectClaudeMcp } from "./mcp.js";
import { installationPaths } from "./paths.js";
import { readInstallState } from "./state.js";

export interface StatusCheck {
  id: string;
  status: "pass" | "warn" | "failure";
  summary: string;
}

export interface StatusReport {
  installed: boolean;
  healthy: boolean;
  installedVersion?: string;
  packageVersion: string;
  checks: StatusCheck[];
}

async function readOwnVersion(): Promise<string> {
  const path = join(packageRoot(import.meta.url), "package.json");
  const value: unknown = JSON.parse(await readFile(path, "utf8"));
  if (!isJsonObject(value) || typeof value.version !== "string") {
    throw new TypeError(`${path} has no version`);
  }
  return value.version;
}

export async function collectStatus(): Promise<StatusReport> {
  const paths = installationPaths();
  const packageVersion = await readOwnVersion();
  const state = await readInstallState();
  const checks: StatusCheck[] = [];

  if (state === null) {
    return {
      installed: false,
      healthy: false,
      packageVersion,
      checks: [
        {
          id: "state",
          status: "failure",
          summary: `No installation state at ${paths.state}. Run browserjack setup.`,
        },
      ],
    };
  }

  checks.push({
    id: "state",
    status: "pass",
    summary: `Installed version ${state.version} (MCP ${state.mcpRegistered ? state.mcpName : "not registered"})`,
  });

  let healthy = true;

  try {
    const linkInfo = await lstat(paths.current);
    if (!linkInfo.isSymbolicLink()) {
      throw new Error(`${paths.current} is not a symlink`);
    }
    const target = await readlink(paths.current);
    const resolved = await realpath(paths.current);
    await access(join(resolved, "dist", "cli.js"));
    checks.push({
      id: "current",
      status: "pass",
      summary: `current -> ${target}`,
    });
  } catch (error) {
    healthy = false;
    checks.push({
      id: "current",
      status: "failure",
      summary: `Broken current release link: ${error instanceof Error ? error.message : String(error)}`,
    });
  }

  try {
    await access(paths.shim);
    checks.push({ id: "shim", status: "pass", summary: `Shim at ${paths.shim}` });
  } catch {
    healthy = false;
    checks.push({
      id: "shim",
      status: "failure",
      summary: `Missing shim at ${paths.shim}. Run browserjack setup.`,
    });
  }

  try {
    await access(state.nodePath);
    checks.push({
      id: "node",
      status: "pass",
      summary: `Shim Node.js at ${state.nodePath}`,
    });
  } catch {
    healthy = false;
    checks.push({
      id: "node",
      status: "failure",
      summary: `Shim Node.js path ${state.nodePath} no longer exists (Node was updated or removed). Run browserjack setup to repair.`,
    });
  }

  if (state.mcpRegistered) {
    try {
      const ownership = await inspectClaudeMcp(state.mcpName, paths.shim, state.registrationCwd);
      if (ownership === "owned") {
        checks.push({
          id: "mcp",
          status: "pass",
          summary: `Claude Code MCP server ${state.mcpName} (${state.mcpScope}) points at this installation`,
        });
      } else if (ownership === "absent") {
        healthy = false;
        checks.push({
          id: "mcp",
          status: "failure",
          summary: `Claude Code MCP server ${state.mcpName} is missing. Run browserjack setup.`,
        });
      } else {
        healthy = false;
        checks.push({
          id: "mcp",
          status: "failure",
          summary: `Claude Code MCP server ${state.mcpName} exists but no longer points at this installation.`,
        });
      }
    } catch (error) {
      checks.push({
        id: "mcp",
        status: "warn",
        summary: `Could not query Claude Code MCP registration: ${error instanceof Error ? error.message : String(error)}`,
      });
    }
  }

  if (state.version !== packageVersion) {
    checks.push({
      id: "version",
      status: "warn",
      summary: `Installed ${state.version} differs from this package ${packageVersion}. Run browserjack update.`,
    });
  }

  return {
    installed: true,
    healthy,
    installedVersion: state.version,
    packageVersion,
    checks,
  };
}

export function printStatusReport(report: StatusReport): void {
  for (const check of report.checks) {
    const marker = check.status === "pass" ? "✓" : check.status === "warn" ? "!" : "✗";
    process.stdout.write(`${marker} ${check.summary}\n`);
  }
  process.stdout.write(`\n${report.installed && report.healthy ? "Healthy" : "Needs attention"}\n`);
}

import {
  chmod,
  cp,
  lstat,
  mkdir,
  readFile,
  readlink,
  rename,
  rm,
  symlink,
  writeFile,
} from "node:fs/promises";
import { join, relative } from "node:path";

import { isJsonObject } from "../lib/json.js";
import { packageRoot } from "../lib/package-root.js";
import { registerClaudeMcp, removeClaudeMcpIfOwned } from "./mcp.js";
import { installationPaths } from "./paths.js";

interface PackageMetadata {
  name: string;
  version: string;
}

export interface SetupOptions {
  scope: "user" | "local" | "project";
  mcpName: string;
  registerMcp: boolean;
  // Directory Claude Code runs `mcp` commands in. Matters for local/project scope.
  cwd?: string;
}

export interface SetupResult {
  version: string;
  releasePath: string;
  shimPath: string;
  mcp: "created" | "unchanged" | "skipped";
}

function shellQuote(value: string): string {
  return `'${value.replaceAll("'", `'"'"'`)}'`;
}

async function readPackageMetadata(root: string): Promise<PackageMetadata> {
  const value: unknown = JSON.parse(await readFile(join(root, "package.json"), "utf8"));
  if (!isJsonObject(value) || typeof value.name !== "string" || typeof value.version !== "string") {
    throw new TypeError("package.json has no name or version");
  }
  return { name: value.name, version: value.version };
}

async function currentTarget(path: string): Promise<string | null> {
  try {
    const info = await lstat(path);
    return info.isSymbolicLink() ? await readlink(path) : null;
  } catch {
    return null;
  }
}

async function readFileOrNull(path: string): Promise<string | null> {
  try {
    return await readFile(path, "utf8");
  } catch {
    return null;
  }
}

async function restoreSymlink(path: string, target: string | null, pid: number): Promise<void> {
  if (target === null) {
    await rm(path, { force: true });
    return;
  }
  const temporary = `${path}.restore-${pid}`;
  await rm(temporary, { force: true });
  await symlink(target, temporary);
  await rename(temporary, path);
}

async function restoreFile(path: string, content: string | null): Promise<void> {
  if (content === null) {
    await rm(path, { force: true, recursive: true });
    return;
  }
  await rm(path, { force: true, recursive: true });
  await writeFile(path, content, { mode: 0o600 });
}

async function installRelease(sourceRoot: string, releasePath: string): Promise<void> {
  try {
    await lstat(releasePath);
    return;
  } catch {
    // Install the missing immutable release.
  }

  const staging = `${releasePath}.staging-${process.pid}`;
  await rm(staging, { recursive: true, force: true });
  await mkdir(staging, { recursive: true, mode: 0o700 });
  // The shim only ever runs dist/cli.js against the compatibility manifest;
  // everything else would be dead weight duplicated into every release.
  for (const entry of ["dist", "compatibility", "package.json", "LICENSE"]) {
    await cp(join(sourceRoot, entry), join(staging, entry), {
      recursive: true,
      force: false,
    });
  }
  await rename(staging, releasePath);
}

export async function setupBridge(options: SetupOptions): Promise<SetupResult> {
  const sourceRoot = packageRoot(import.meta.url);
  const metadata = await readPackageMetadata(sourceRoot);
  const paths = installationPaths();
  const releasePath = join(paths.releases, metadata.version);

  await mkdir(paths.releases, { recursive: true, mode: 0o700 });
  await mkdir(paths.bin, { recursive: true, mode: 0o700 });
  await installRelease(sourceRoot, releasePath);

  const previousTarget = await currentTarget(paths.current);
  const previousShim = await readFileOrNull(paths.shim);
  const previousState = await readFileOrNull(paths.state);

  const nextTarget = relative(paths.root, releasePath);
  const temporaryLink = `${paths.current}.next-${process.pid}`;
  await rm(temporaryLink, { force: true });
  await symlink(nextTarget, temporaryLink);
  await rename(temporaryLink, paths.current);

  const shim = `#!/bin/sh\nexec ${shellQuote(process.execPath)} ${shellQuote(
    join(paths.current, "dist", "cli.js"),
  )} "$@"\n`;
  await writeFile(paths.shim, shim, { mode: 0o755 });
  await chmod(paths.shim, 0o755);

  const registrationCwd = options.cwd ?? process.cwd();
  let mcp: "created" | "unchanged" | "skipped" = "skipped";
  try {
    mcp = options.registerMcp
      ? await registerClaudeMcp(options.mcpName, paths.shim, options.scope, registrationCwd)
      : "skipped";
    await writeFile(
      paths.state,
      `${JSON.stringify(
        {
          schemaVersion: 1,
          packageName: metadata.name,
          version: metadata.version,
          nodePath: process.execPath,
          mcpName: options.mcpName,
          mcpScope: options.scope,
          mcpRegistered: options.registerMcp,
          registrationCwd,
        },
        null,
        2,
      )}\n`,
      { mode: 0o600 },
    );
    return {
      version: metadata.version,
      releasePath,
      shimPath: paths.shim,
      mcp,
    };
  } catch (error) {
    if (mcp === "created") {
      await removeClaudeMcpIfOwned(
        options.mcpName,
        paths.shim,
        options.scope,
        registrationCwd,
      ).catch(() => {
        // Best-effort undo of the registration created in this run.
      });
    }
    await restoreFile(paths.state, previousState);
    await restoreFile(paths.shim, previousShim);
    if (previousShim !== null) {
      await chmod(paths.shim, 0o755).catch(() => {});
    }
    await restoreSymlink(paths.current, previousTarget, process.pid);
    throw error;
  }
}

{
  "mcpServers": {
    "browserjack": {
      "command": "${CLAUDE_PLUGIN_ROOT}/bin/browserjack-mcp"
    }
  }
}
